  a { text-underline-offset: 0.18em; text-decoration-thickness: 1px; }
  ::selection { background: rgb(var(--na-bg)); color: rgb(var(--ink)); }
}

@layer components {
  /* field labels: mono small caps, inline */
  .label { font-family: theme('fontFamily.mono'); font-size: 0.75rem; letter-spacing: 0.06em; text-transform: uppercase; color: rgb(var(--muted)); }
  .link { color: inherit; text-decoration-line: underline; text-decoration-color: rgb(var(--ink) / 0.35); }
  .press { transition: transform 160ms ease-out; }
  .press:active { transform: scale(0.97); }
}

@media (hover: hover) and (pointer: fine) {
  .link { transition: text-decoration-color 120ms ease-out; }
  .link:hover { text-decoration-color: rgb(var(--ink)); }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  html { scroll-behavior: auto; }
}

@media (hover: hover) and (pointer: fine) {
  .hover-underline { transition: text-decoration-color 120ms ease-out; }
  .hover-underline:hover { text-decoration-color: rgb(var(--ink)); }
  .hover-ink { transition: color 120ms ease-out; }
  .hover-ink:hover { color: rgb(var(--ink)); }
}

/* ---------- Fig. 1: the ledger sheet ---------- */
/* double red margin rule after the accession column: two 1px lines, 3px apart */
.ledger-acc {
  box-shadow:
    inset -1px 0 0 rgb(var(--margin) / var(--margin-alpha)),
    inset -4px 0 0 rgb(var(--ledger)),
    inset -5px 0 0 rgb(var(--margin) / var(--margin-alpha));
  padding-right: 1.1rem;
}
.cell-btn:focus-visible { outline-offset: -4px; }

/* the replay range: plain, ink-on-rule */
.replay-range { appearance: none; background: transparent; height: 2.75rem; cursor: pointer; }
.replay-range::-webkit-slider-runnable-track { height: 2px; background: rgb(var(--ink) / 0.5); }
.replay-range::-moz-range-track { height: 2px; background: rgb(var(--ink) / 0.5); }
.replay-range::-webkit-slider-thumb { appearance: none; width: 18px; height: 18px; margin-top: -8px; border-radius: 50%; background: rgb(var(--ink)); border: 3px solid rgb(var(--surface)); box-shadow: 0 0 0 1px rgb(var(--ink)); }
.replay-range::-moz-range-thumb { width: 14px; height: 14px; border-radius: 50%; background: rgb(var(--ink)); border: 3px solid rgb(var(--surface)); }

/* ---------- Sheet motion: 280ms in, 200ms out ---------- */
@keyframes sheet-in-right { from { transform: translateX(100%); } to { transform: translateX(0); } }
@keyframes sheet-out-right { from { transform: translateX(0); } to { transform: translateX(100%); } }
@keyframes sheet-in-bottom { from { transform: translateY(100%); } to { transform: translateY(0); } }
@keyframes sheet-out-bottom { from { transform: translateY(0); } to { transform: translateY(100%); } }
@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes fade-out { from { opacity: 1; } to { opacity: 0; } }
.sheet[data-state='open'][data-side='right'] { animation: sheet-in-right 280ms cubic-bezier(0.32, 0.72, 0, 1); }
.sheet[data-state='closed'][data-side='right'] { animation: sheet-out-right 200ms cubic-bezier(0.32, 0.72, 0, 1); }
.sheet[data-state='open'][data-side='bottom'] { animation: sheet-in-bottom 280ms cubic-bezier(0.32, 0.72, 0, 1); }
.sheet[data-state='closed'][data-side='bottom'] { animation: sheet-out-bottom 200ms cubic-bezier(0.32, 0.72, 0, 1); }
.sheet-overlay[data-state='open'] { animation: fade-in 280ms ease-out; }
.sheet-overlay[data-state='closed'] { animation: fade-out 200ms ease-in; }

/* sticky register header on desktop (the sheet stops being a scroll container from lg) */
@media (min-width: 1024px) {
  .ledger thead th {
    position: sticky;
    top: 3.5rem; /* under the nav */
    z-index: 20;
    background: rgb(var(--ledger));
    box-shadow: inset 0 -2px 0 rgb(var(--ledger-rule));
  }
  .ledger thead th.ledger-acc {
    z-index: 30;
    box-shadow:
      inset 0 -2px 0 rgb(var(--ledger-rule)),
