      inset -4px 0 0 rgb(var(--ledger)),
      inset -5px 0 0 rgb(var(--margin) / var(--margin-alpha));
  }
}

/* the row a mini-register square jumped to: a static outline until the next click elsewhere */
[data-row][data-hit] { outline: 2px solid rgb(var(--ink)); outline-offset: -2px; }

