import { useEffect, useRef, useState } from 'react';
import { Pause, Play, RotateCcw } from 'lucide-react';
import { shortDate, site } from '@/lib/site';
import { cn } from '@/lib/utils';

const STEP_MS = 1000; // 8 stops ≈ 8 s

// stops sit on the track in proportion to real time (days since the first stop)
const dayOf = (iso: string) => Date.UTC(+iso.slice(0, 4), +iso.slice(5, 7) - 1, +iso.slice(8, 10)) / 86_400_000;
const DAYS = site.stops.map((s) => dayOf(s.date) - dayOf(site.stops[0]!.date));
const total = DAYS.at(-1)!;
const nearest = (d: number) => DAYS.reduce((best, x, i) => (Math.abs(x - d) < Math.abs(DAYS[best]! - d) ? i : best), 0);
// the native thumb is 18 px wide, so its centre runs from 9 px to (100% - 9 px)
const pos = (d: number) => `calc(9px + (100% - 18px) * ${d / total})`;
const at = (i: number) => ({ left: pos(DAYS[i]!) });
const span = (a: number, b: number) => ({ left: pos(DAYS[a]!), width: `calc((100% - 18px) * ${(DAYS[b]! - DAYS[a]!) / total})` });

// the October cluster: Ubuntu's patch (label to the left of its tick) and Django's amendment
// (label to the right, in the gutter) share a second row, with the quiet "n days" band between them
const conn = site.connector;
const distroIdx = site.stops.findIndex((s) => s.kind === 'distro');
const amendIdx = conn ? site.stops.findIndex((s) => s.kind === 'advisories' && s.date === conn.date) : -1;
const band = distroIdx >= 0 && amendIdx > distroIdx ? { from: distroIdx, to: amendIdx, days: DAYS[amendIdx]! - DAYS[distroIdx]! } : null;
type Place = { row: 0 | 1; align: 'first' | 'center' | 'start' | 'end' };
const PLACE: Place[] = site.stops.map((_, i) => {
  if (i === 0) return { row: 0, align: 'first' };
  if (band && i === band.from) return { row: 1, align: 'end' };
  if (band && i === band.to) return { row: 1, align: 'start' };
  if (i === site.stops.length - 1) return { row: 0, align: 'start' };
  return { row: 0, align: 'center' };
});

/** The campaign replay: a native range input over the dated stops, with an opt-in play button. */
export function Replay({
  stop,
  count,
  onStop,
  onReplayStart,
}: {
  stop: number;
  count: number;
  onStop: (i: number) => void;
  onReplayStart: () => void;
}) {
  const last = site.stops.length - 1;
  const [playing, setPlaying] = useState(false);
  const timer = useRef<number>();
  const cur = site.stops[stop]!;

  useEffect(() => {
    if (!playing) return;
    if (stop >= last) {
      setPlaying(false);
      return;
    }
    timer.current = window.setTimeout(() => onStop(stop + 1), STEP_MS);
    return () => window.clearTimeout(timer.current);
  }, [playing, stop, last, onStop]);

  const start = () => {
    onReplayStart();
    if (stop >= last) onStop(0);
    setPlaying(true);
  };

  const go = (i: number) => {
    setPlaying(false);
    onReplayStart();
    onStop(Math.max(0, Math.min(last, i)));
  };
  const onKey = (e: React.KeyboardEvent) => {
    const map: Record<string, number> = {
      ArrowRight: stop + 1,
      ArrowUp: stop + 1,
      PageUp: stop + 1,
      ArrowLeft: stop - 1,
      ArrowDown: stop - 1,
      PageDown: stop - 1,
      Home: 0,
      End: last,
    };
    if (e.key in map) {
      e.preventDefault();
      go(map[e.key]!);
    }
  };

  const status = `${shortDate(cur.date)} · ${cur.kind === 'advisories' ? '' : cur.label + ' · '}${count} of ${site.rows.length} advisories`;

  return (
    <div className="mt-8 rounded-[2px] border border-rule bg-surface px-4 py-4 md:px-5">
      <div className="flex flex-wrap items-center gap-x-5 gap-y-2">
        <button
          type="button"
          onClick={playing ? () => setPlaying(false) : start}
          className="press inline-flex min-h-11 items-center gap-2 text-base underline decoration-ink/40 underline-offset-[0.2em] hover-underline"
        >
          {playing ? <Pause className="h-4 w-4" aria-hidden /> : stop >= last ? <RotateCcw className="h-4 w-4" aria-hidden /> : <Play className="h-4 w-4" aria-hidden />}
          {playing ? 'Pause' : stop >= last ? 'Replay the campaign' : 'Play'}
        </button>
        <p aria-live="polite" className="font-mono text-[0.8rem] tabular-nums text-ink">
          {status.split(/(CVE-\d{4}-\d+)/).map((t, i) => (i % 2 ? <span key={i} className="whitespace-nowrap">{t}</span> : t))}
        </p>
      </div>
      <label htmlFor="replay" className="sr-only">
        Campaign date
      </label>
      {/* the track leaves a gutter on the right for the labels of the October cluster */}
      <div className="mt-3 md:pr-16 lg:pr-[16rem]">
        <div className="relative">
          {band && (
            <div aria-hidden className="pointer-events-none absolute inset-y-0 hidden md:block" style={span(band.from, band.to)}>
              <span className="absolute inset-x-0 top-[13px] h-[18px] bg-ink/[0.08]" />
              <span className="absolute left-1/2 top-0 -translate-x-1/2 whitespace-nowrap font-mono text-[0.62rem] leading-none text-muted">
                {band.days} days
              </span>
            </div>
          )}
          <input
            id="replay"
            type="range"
            min={0}
            max={total}
            step={1}
            value={DAYS[stop]}
            aria-valuetext={status}
            onKeyDown={onKey}
            onChange={(e) => go(nearest(Number(e.target.value)))}
            className="replay-range relative w-full"
          />
        </div>
        <ol className="relative mt-0.5 hidden h-10 md:block lg:h-[5.5rem]" aria-hidden>
          {site.stops.map((s, i) => {
            const place = PLACE[i]!;
            const cur = i === stop;
            const label = i === amendIdx && conn ? `${s.label}, incl. ${conn.from}: Django amends its ${conn.to} fix` : s.label;
            return (
              <li key={s.date + s.kind} className={cn('absolute top-0', cur ? 'text-ink' : 'text-muted')} style={at(i)}>
                {/* tick, and a leader down to the second label row */}
                <span className={cn('absolute left-0 top-0 w-px -translate-x-1/2', cur ? 'bg-ink' : 'bg-muted/60', place.row ? 'h-[18px] lg:h-[34px]' : 'h-[5px]')} />
                <span
                  className={cn(
                    'absolute whitespace-nowrap font-mono text-[0.65rem] leading-tight lg:whitespace-normal',
                    place.row ? 'top-[19px] lg:top-[35px]' : 'top-[7px]',
                    place.align === 'center' && 'w-[3.5rem] -translate-x-1/2 text-center lg:w-[7.5rem]',
                    place.align === 'start' && 'left-0 pl-1 text-left lg:w-[15rem]',
                    place.align === 'first' && '-left-[9px] text-left lg:w-[7.5rem]',
                    place.align === 'end' && 'right-0 pr-1 text-right lg:w-[15rem]',
                  )}
                >
                  <span className={cn('block tabular-nums', cur && 'font-medium')}>{s.date.slice(5)}</span>
                  <span className="hidden lg:block">{label}</span>
                </span>
              </li>
            );
          })}
        </ol>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { m } from 'motion/react';
import type { Chip as ChipT, LineId, Row } from '@/data/types';
import { CHIP_META, lineById, shortDate, site } from '@/lib/site';
import { Chip, ChipLegend } from './Chip';
import { RstTitle } from './Code';
import { Replay } from './Replay';
import { onGoto, type Goto } from '@/lib/goto';
import { useMedia } from '@/lib/useMedia';
import { ToggleGroup, ToggleGroupItem } from './ui/toggle-group';

export type OpenReceipt = (anchor: string, line: LineId, trigger: HTMLElement | null) => void;
type Filter = ChipT | 'ALL';

const INK = { duration: 0.18, ease: [0.23, 1, 0.32, 1] as const };
const LINES = site.lines.map((l) => l.id);

function rowTotal(r: Row) {
  const undecided = r.cells.filter((c) => c.chip === 'UNPROVEN' || c.chip === 'NO_PROBE').length;
  const n = r.cells.length;
  if (undecided === n) return `none of ${n} decided`;
  return `${r.affected} of ${n} lines affected` + (undecided ? ` · ${undecided} undecided` : '');
}

export function Register({ onOpen }: { onOpen: OpenReceipt }) {
  const last = site.stops.length - 1;
  // only the layout that applies is rendered: the ledger table from md, cards below
  const wide = useMedia('(min-width: 768px)');
  const xl = useMedia('(min-width: 1280px)');
  const [stop, setStop] = useState(last); // default: the end, everything visible
  const [animate, setAnimate] = useState(false); // ink-in only once the visitor replays
  const [filter, setFilter] = useState<Filter>('ALL');
  const until = site.stops[stop]!.date;

  const arrived = useMemo(() => site.rows.filter((r) => r.date <= until), [until]);
  const counts = useMemo(() => {
    const c = Object.fromEntries(site.chips.map((k) => [k, 0])) as Record<ChipT, number>;
    for (const r of arrived) for (const cell of r.cells) c[cell.chip]++;
    return c;
  }, [arrived]);
  const shown = useMemo(
    () => (filter === 'ALL' ? arrived : arrived.filter((r) => r.cells.some((c) => c.chip === filter))),
    [arrived, filter],
  );
  const shownSet = useMemo(() => new Set(shown.map((r) => r.anchor)), [shown]);
  // batch position, for the ink-in stagger
  const batchIndex = useMemo(() => {
    const seen = new Map<string, number>();
    return new Map(
      site.rows.map((r) => [r.anchor, (seen.set(r.date, (seen.get(r.date) ?? -1) + 1), seen.get(r.date)) as number]),
    );
  }, []);

  // ---- roving tabindex over the visible cell buttons ----
  const [pos, setPos] = useState<[number, number]>([0, 0]);
  const cellRefs = useRef(new Map<string, HTMLButtonElement>());
  const key = (anchor: string, col: number) => `${anchor}|${col}`;
  const safePos: [number, number] = [Math.min(pos[0], Math.max(shown.length - 1, 0)), pos[1]];
  const move = useCallback(
    (r: number, c: number) => {
      const rr = Math.max(0, Math.min(shown.length - 1, r));
      const cc = Math.max(0, Math.min(LINES.length - 1, c));
      setPos([rr, cc]);
      const row = shown[rr];
      if (row) cellRefs.current.get(key(row.anchor, cc))?.focus();
    },
    [shown],
  );
  const onKey = (e: React.KeyboardEvent, r: number, c: number) => {
    const map: Record<string, () => void> = {
      ArrowRight: () => move(r, c + 1),
      ArrowLeft: () => move(r, c - 1),
      ArrowDown: () => move(r + 1, c),
      ArrowUp: () => move(r - 1, c),
      Home: () => move(e.ctrlKey ? 0 : r, 0),
      End: () => move(e.ctrlKey ? shown.length - 1 : r, LINES.length - 1),
      PageDown: () => move(r + 5, c),
      PageUp: () => move(r - 5, c),
    };
    const f = map[e.key];
    if (f) {
      e.preventDefault();
      f();
    }
  };

  // ---- jumps from the hero's mini register: show everything, then focus the cell ----
  const [hit, setHit] = useState<string | null>(null);
  const [pending, setPending] = useState<Goto | null>(null);
  useEffect(
    () =>
      onGoto((g) => {
        setFilter('ALL');
        setStop(last);
        setHit(g.anchor);
        setPending({ ...g });
      }),
    [last],
  );
  useEffect(() => {
    if (!pending) return;
    const el = wide
      ? cellRefs.current.get(key(pending.anchor, pending.col))
      : document.querySelector<HTMLElement>(`[data-card="${pending.anchor}|${pending.col}"]`);
    if (el) {
      // desktop: centre the row; mobile: the whole card, its top under the nav
      (wide ? el : (el.closest('li[data-row]') ?? el)).scrollIntoView({ block: wide ? 'center' : 'start' });
      el.focus({ preventScroll: true });
    }
    setPending(null);
  }, [pending, wide]);
  useEffect(() => {
    if (!hit) return;
    const clear = (e: PointerEvent) => {
      if (!(e.target as Element).closest?.(`[data-row="${hit}"]`)) setHit(null);
    };
    document.addEventListener('pointerdown', clear);
    return () => document.removeEventListener('pointerdown', clear);
  }, [hit]);

  // ---- the 87890 → 15307 connector, drawn in the right margin ----
  const sheetRef = useRef<HTMLDivElement>(null);
  const rowRefs = useRef(new Map<string, HTMLTableRowElement>());
  const [geo, setGeo] = useState<{ y1: number; y2: number; x: number } | null>(null);
  const conn = site.connector;
  const fromRow = conn && site.rows.find((r) => r.cve === conn.from);
  const toRow = conn && site.rows.find((r) => r.cve === conn.to);
  const showConn = Boolean(
    conn && until >= conn.date && fromRow && toRow && shownSet.has(fromRow.anchor) && shownSet.has(toRow.anchor),
  );
  const measure = useCallback(() => {
    const sheet = sheetRef.current;
    if (!xl) return setGeo(null); // the connector is drawn only at xl; skip the layout reads
    const a = fromRow && rowRefs.current.get(fromRow.anchor);
    const b = toRow && rowRefs.current.get(toRow.anchor);
    if (!sheet || !a || !b) return setGeo(null);
    const s = sheet.getBoundingClientRect();
    const ra = a.getBoundingClientRect();
    const rb = b.getBoundingClientRect();
    setGeo({ y1: ra.top - s.top + ra.height / 2, y2: rb.top - s.top + rb.height / 2, x: ra.right - s.left });
  }, [fromRow, toRow, xl]);
  useLayoutEffect(() => {
    measure();
  }, [measure, shown, showConn]);
  useEffect(() => {
    const ro = new ResizeObserver(measure);
    if (sheetRef.current) ro.observe(sheetRef.current);
    return () => ro.disconnect();
  }, [measure]);

  const liveCount =
    filter === 'ALL'
      ? `${shown.length} of ${site.rows.length} advisories shown`
      : `${shown.length} of ${arrived.length} advisories have a ${CHIP_META[filter].word.toUpperCase()} cell`;

  return (
    <section id="register" aria-labelledby="fig1" className="border-t border-rule pt-10">
      <figure className="m-0">
        <figcaption className="grid gap-2 md:grid-cols-12">
          <h2 id="fig1" className="text-3xl leading-tight md:col-span-8 md:text-4xl">
            Fig. 1 — The register.
          </h2>
          <p className="text-lg text-muted md:col-span-8">Every cell is a test run you can open.</p>
        </figcaption>

        <Replay stop={stop} count={arrived.length} onStop={(i) => setStop(i)} onReplayStart={() => setAnimate(true)} />

        <div className="mt-6 flex flex-wrap items-center gap-x-4 gap-y-3">
          <span className="label" id="filter-label">
            Filter
          </span>
          <ToggleGroup
            type="single"
            value={filter}
            onValueChange={(v) => setFilter((v || 'ALL') as Filter)}
            aria-labelledby="filter-label"
          >
            <ToggleGroupItem value="ALL">
              All <span className="tabular-nums">{arrived.length}</span>
            </ToggleGroupItem>
            {site.chips.map((c) => (
              <ToggleGroupItem key={c} value={c}>
                <span aria-hidden>{CHIP_META[c].symbol}</span> {CHIP_META[c].word}{' '}
                <span className="tabular-nums">{counts[c]}</span>
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
          <p aria-live="polite" className="w-full font-mono text-xs text-muted md:ml-auto md:w-auto">
            {liveCount}
          </p>
        </div>

        {/* desktop/tablet: the ledger sheet */}
        {wide && (
          <div ref={sheetRef} className="relative mt-5 xl:pr-44">
            <div className="overflow-x-auto rounded-[2px] border border-ledger-rule bg-ledger lg:overflow-visible">
              <p id="register-help" className="sr-only">
                Each verdict cell is a button. Use the arrow keys to move between cells, Home and End for the start or
                end of a row, and Enter to open the receipt.
              </p>
              <table className="ledger w-full table-fixed border-collapse text-left" aria-describedby="register-help">
                <colgroup>
                  <col className="w-[7.25rem]" />
                  <col />
                  {site.lines.map((l) => (
                    <col key={l.id} className="w-[8.25rem] lg:w-[9rem] xl:w-[10rem]" />
                  ))}
                  <col className="hidden w-[11rem] lg:table-column" />
                </colgroup>
                <thead>
                  <tr className="border-b-2 border-ledger-rule align-bottom lg:border-b-0">
                    <th scope="col" className="ledger-acc sticky left-0 z-10 bg-ledger px-3 py-3 label">
                      Accession
                    </th>
                    <th scope="col" className="px-4 py-3 label">
                      Advisory
                    </th>
                    {site.lines.map((l) => (
                      <th key={l.id} scope="col" className="px-2 py-3 font-normal">
                        <span className="block text-[0.95rem] leading-tight">{l.label}</span>
                        <span className="mt-0.5 block font-mono text-[0.7rem] text-muted [overflow-wrap:anywhere]">
                          {l.kind === 'eval' ? 'tag ' + l.version : l.version}
                        </span>
                      </th>
                    ))}
                    <th scope="col" className="hidden whitespace-nowrap px-3 py-3 label lg:table-cell">
                      Lines affected
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {site.rows.map((r) => {
                    const isArrived = r.date <= until;
                    const visible = shownSet.has(r.anchor);
                    if (isArrived && !visible) return null;
                    const ri = shown.indexOf(r);
                    const delay = animate ? (batchIndex.get(r.anchor) ?? 0) * 0.045 : 0;
                    const ink = animate
                      ? {
                          initial: { opacity: 0, scale: 0.96 },
                          animate: { opacity: 1, scale: 1 },
                          transition: { ...INK, delay },
                        }
                      : { initial: false as const };
                    return (
                      <tr
                        key={r.anchor}
                        ref={(el) => {
                          if (el) rowRefs.current.set(r.anchor, el);
                          else rowRefs.current.delete(r.anchor);
                        }}
                        className="border-b border-ledger-rule"
                        data-row={r.anchor}
                        data-hit={hit === r.anchor ? '' : undefined}
                        aria-hidden={isArrived ? undefined : true}
                      >
                        <th
                          scope="row"
                          className="ledger-acc sticky left-0 z-10 bg-ledger px-3 py-2 text-left align-middle font-mono text-[0.8rem] font-normal"
                        >
                          <span className={isArrived ? 'whitespace-nowrap' : 'whitespace-nowrap text-muted'}>
                            {r.acc}
                          </span>
                        </th>
                        {isArrived ? (
                          <>
                            <td className="px-4 py-2 align-middle [overflow-wrap:break-word]">
                              <m.div {...ink}>
                                <span className="whitespace-nowrap font-mono text-[0.8rem]">{r.cve}</span>
                                {site.query_marker.cve === r.cve && (
                                  <span className="ml-2 rounded-chip border border-ink/30 px-1 py-px font-mono text-[0.65rem] uppercase tracking-wide">
                                    query #{site.query_marker.number}
                                  </span>
                                )}
                                <span className="block text-[0.95rem] leading-snug">
                                  <RstTitle text={r.title} />
                                </span>
                                <span className="mt-0.5 block font-mono text-[0.7rem] text-muted lg:hidden">
                                  {rowTotal(r)}
                                </span>
                                {conn && r.cve === conn.from && until >= conn.date && (
                                  <span className="mt-0.5 block font-mono text-[0.7rem] text-muted xl:sr-only">
                                    stacked on our own backport · PR #{conn.pr} on #{conn.on}
                                  </span>
                                )}
                              </m.div>
                            </td>
                            {r.cells.map((cell, ci) => {
                              const line = lineById[cell.line];
                              const active = safePos[0] === ri && safePos[1] === ci;
                              const match = filter !== 'ALL' && cell.chip === filter;
                              return (
                                <td key={cell.line} className="p-0 align-middle">
                                  <button
                                    type="button"
                                    ref={(el) => {
                                      if (el) cellRefs.current.set(key(r.anchor, ci), el);
                                      else cellRefs.current.delete(key(r.anchor, ci));
                                    }}
                                    tabIndex={active ? 0 : -1}
                                    onFocus={() => setPos([ri, ci])}
                                    onKeyDown={(e) => onKey(e, ri, ci)}
                                    onClick={(e) => onOpen(r.anchor, cell.line, e.currentTarget)}
                                    aria-label={`${r.cve} on ${line.label}: ${CHIP_META[cell.chip].word}. Open receipt`}
                                    className="cell-btn press flex min-h-12 w-full items-center px-2 py-2 text-left"
                                  >
                                    <m.span {...ink} className="inline-flex">
                                      <Chip
                                        chip={cell.chip}
                                        className={match ? 'outline outline-1 outline-offset-2 outline-ink' : ''}
                                      />
                                    </m.span>
                                  </button>
                                </td>
                              );
                            })}
                            <td className="hidden px-3 py-2 align-middle font-mono text-[0.75rem] text-muted lg:table-cell">
                              <m.span {...ink} className="block">
                                {rowTotal(r)
                                  .split(' · ')
                                  .map((t) => (
                                    <span key={t} className="block whitespace-nowrap">
                                      {t}
                                    </span>
                                  ))}
                              </m.span>
                            </td>
                          </>
                        ) : (
                          <td colSpan={2 + site.lines.length} className="px-4 py-2 align-middle">
                            <span className="block min-h-[2.6rem]" />
                          </td>
                        )}
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
            {showConn && geo && conn && (
              <Connector geo={geo} label={['stacked on our own backport', `PR #${conn.pr} on #${conn.on}`]} />
            )}
          </div>
        )}

        {/* mobile: one card per CVE */}
        {!wide && (
          <ol className="mt-5 grid gap-3" aria-label="Register entries">
            {shown.map((r) => (
              <li
                key={r.anchor}
                data-row={r.anchor}
                data-hit={hit === r.anchor ? '' : undefined}
                className="min-w-0 rounded-[2px] border border-ledger-rule bg-ledger p-4"
              >
                <p className="flex items-baseline justify-between gap-3 font-mono text-[0.75rem] text-muted">
                  <span>{r.acc}</span>
                  <span>{shortDate(r.date)}</span>
                </p>
                <p className="mt-1 font-mono text-sm">
                  {r.cve}
                  {site.query_marker.cve === r.cve && (
                    <span className="ml-2 rounded-chip border border-ink/30 px-1 py-px text-[0.65rem] uppercase">
                      query #{site.query_marker.number}
                    </span>
                  )}
                </p>
                <p className="mt-1 leading-snug [overflow-wrap:anywhere]">
                  <RstTitle text={r.title} />
                </p>
                {conn && r.cve === conn.from && until >= conn.date && (
                  <p className="mt-1 font-mono text-[0.7rem] text-muted">
                    stacked on our own backport · PR #{conn.pr} on #{conn.on}
                  </p>
                )}
                <ul className="mt-3 divide-y divide-ledger-rule border-t border-ledger-rule">
                  {r.cells.map((cell, ci) => {
                    const line = lineById[cell.line];
                    return (
                      <li key={cell.line}>
                        <button
                          type="button"
                          data-card={`${r.anchor}|${ci}`}
                          onClick={(e) => onOpen(r.anchor, cell.line, e.currentTarget)}
                          className="press flex min-h-12 w-full items-center justify-between gap-3 py-2 text-left"
                        >
                          <span className="text-[0.9rem] leading-tight">
                            <span className="sr-only">{r.cve} on </span>
                            {line.label}
                          </span>
                          <Chip chip={cell.chip} />
                          <span className="sr-only">. Open receipt</span>
                        </button>
                      </li>
                    );
                  })}
                </ul>
                <p className="mt-2 font-mono text-[0.7rem] text-muted">{rowTotal(r)}</p>
              </li>
            ))}
          </ol>
        )}

        <div className="mt-6 border-t border-rule pt-4">
          <ChipLegend />
        </div>
      </figure>
    </section>
  );
}

function Connector({ geo, label }: { geo: { y1: number; y2: number; x: number }; label: [string, string] }) {
  const { y1, y2, x } = geo;
  const x0 = x + 6;
  const bend = 28;
  const top = Math.min(y1, y2);
  const d = `M${x0} ${y1} C${x0 + bend} ${y1} ${x0 + bend} ${y1} ${x0 + bend} ${y1 - 14} L${x0 + bend} ${y2 + 14} C${x0 + bend} ${y2} ${x0 + bend} ${y2} ${x0 + 7} ${y2}`;
  return (
    <svg
      aria-hidden
      className="pointer-events-none absolute left-0 top-0 hidden h-full w-full overflow-visible xl:block"
    >
      <path d={d} fill="none" stroke="rgb(var(--ink))" strokeWidth="1" />
      <path d={`M${x0} ${y2} l7 -4 v8 z`} fill="rgb(var(--ink))" />
      <circle cx={x0} cy={y1} r="2.5" fill="rgb(var(--ink))" />
      <text x={x0 + bend + 10} y={top + Math.abs(y1 - y2) / 2 - 4} className="fill-ink font-mono text-[11px]">
        {label[0]}
      </text>
      <text x={x0 + bend + 10} y={top + Math.abs(y1 - y2) / 2 + 12} className="fill-muted font-mono text-[11px]">
        {label[1]}
      </text>
    </svg>
  );
}

import { useEffect, useState } from 'react';
import type { LineId, Receipt as ReceiptT, ReceiptCell, Row } from '@/data/types';
import { CHIP_META, GATES, REASONS, lineById, prNum, shortDate, site } from '@/lib/site';
import { cn } from '@/lib/utils';
import { useMedia } from '@/lib/useMedia';
import { Chip } from './Chip';
import { Breakable, RstTitle } from './Code';
import { FileText, GitPullRequest } from 'lucide-react';
import { CopyButton } from './CopyButton';
import { Sheet, SheetContent, SheetDescription, SheetTitle } from './ui/sheet';
import { Tabs, TabsContent, TabsList, TabsTrigger } from './ui/tabs';

const cache = new Map<string, Promise<ReceiptT>>();
function load(cve: string) {
  let p = cache.get(cve);
  if (!p) {
    p = fetch(`${import.meta.env.BASE_URL}receipts/${cve}.json`).then((r) => {
      if (!r.ok) throw new Error(`receipt ${cve}: ${r.status}`);
      return r.json() as Promise<ReceiptT>;
    });
    cache.set(cve, p);
  }
  return p;
}

export default function Receipt({
  row,
  line,
  onClose,
  onLine,
  returnFocus,
}: {
  row: Row | null;
  line: LineId;
  onClose: () => void;
  onLine: (l: LineId) => void;
  returnFocus: () => void;
}) {
  const wide = useMedia('(min-width: 768px)');
  const [data, setData] = useState<ReceiptT | null>(null);
  const [err, setErr] = useState<string | null>(null);
  useEffect(() => {
    if (!row) return;
    setData(null);
    setErr(null);
    load(row.cve).then(setData, (e: Error) => setErr(e.message));
  }, [row]);

  return (
    <Sheet open={Boolean(row)} onOpenChange={(o) => !o && onClose()}>
      {row && (
        <SheetContent
          side={wide ? 'right' : 'bottom'}
          className="overflow-y-auto overscroll-contain"
          onCloseAutoFocus={(e) => {
            e.preventDefault();
            returnFocus();
          }}
        >
          <div className="px-5 pb-10 pt-5 md:px-8 md:pt-7">
            <header className="pr-12">
              <p className="font-mono text-xs text-muted">
                {row.acc} · advisory {shortDate(row.date)}
              </p>
              <SheetTitle className="mt-1 font-mono text-lg font-medium">{row.cve}</SheetTitle>
              <SheetDescription className="mt-1 text-xl leading-snug text-ink">
                <RstTitle text={row.title} />
              </SheetDescription>
              {row.url && (
                <a className="link mt-2 inline-block text-[0.95rem]" href={row.url}>
                  Django&rsquo;s advisory
                </a>
              )}
            </header>

            <Field name="Condition">
              <ul className="grid gap-2">
                {row.cells.map((c) => (
                  <li key={c.line} className="grid grid-cols-[1fr_auto] items-start gap-x-3">
                    <span className="text-[0.95rem] leading-snug">
                      {lineById[c.line].label}
                      <span className="block font-mono text-[0.7rem] text-muted sm:ml-2 sm:inline">{lineById[c.line].version}</span>
                    </span>
                    <Chip chip={c.chip} className="mt-0.5" />
                  </li>
                ))}
              </ul>
            </Field>

            <Field name="Examination">
              {err && <p className="text-aff-fg">The receipt could not be loaded ({err}).</p>}
              {!data && !err && <p className="text-muted">Loading the runs…</p>}
              {data && (
                <Tabs value={line} onValueChange={(v) => onLine(v as LineId)}>
                  <TabsList aria-label="Release line">
                    {site.lines.map((l) => (
                      <TabsTrigger key={l.id} value={l.id}>
                        {l.name}
                      </TabsTrigger>
                    ))}
                  </TabsList>
                  {data.cells.map((c) => (
                    <TabsContent key={c.line} value={c.line} className="pt-4">
                      <Examination cell={c} row={row} />
                    </TabsContent>
                  ))}
                </Tabs>
              )}
            </Field>

            <Field name="Treatment">
              <Treatment row={row} />
            </Field>

            <Field name="Evidence">
              <Evidence row={row} matrixLogs={data?.matrix_logs} />
            </Field>
          </div>
        </SheetContent>
      )}
    </Sheet>
  );
}

function Field({ name, children }: { name: string; children: React.ReactNode }) {
  return (
    <section className="mt-7 border-t border-rule pt-4">
      <h3 className="label mb-3">{name}</h3>
      {children}
    </section>
  );
}

function times(outcomes: string[] | undefined) {
  if (!outcomes?.length) return '—';
  const same = outcomes.every((o) => o === outcomes[0]);
  return same ? `${outcomes[0]} ×${outcomes.length}` : outcomes.join(' · ');
}

function Examination({ cell, row }: { cell: ReceiptCell; row: Row }) {
  const chip = row.cells.find((c) => c.line === cell.line)!.chip;
  const line = lineById[cell.line];
  const ids = [...new Set([...(cell.runs.um?.failing_ids ?? []), ...(cell.runs.lt?.failing_ids ?? [])])];
  if (cell.verdict === 'no_calibrated_probe') {
    return (
      <p className="text-[0.95rem]">
        No probe passed calibration for this CVE, so nothing was run on {line.label}.
        {row.campaign.reason && REASONS[row.campaign.reason] ? ` In the campaign, ${REASONS[row.campaign.reason]}.` : ''}
      </p>
    );
  }
  return (
    <div className="grid gap-5">
      <figure className="m-0">
        <Triangle um={times(cell.runs.um?.outcomes)} up={times(cell.runs.up?.outcomes)} lt={times(cell.runs.lt?.outcomes)} line={line.name} chip={chip} />
        <figcaption className="mt-2 text-sm text-muted">
          Calibration: the probe on upstream before the fix (U⁻), after it (U⁺), and on {line.label}.
          {cell.detail && <> Result: {cell.detail}.</>}
          {cell.reason && REASONS[cell.reason] && <> Unproven because {REASONS[cell.reason]}.</>}
        </figcaption>
      </figure>
      {ids.length > 0 && (
        <div>
          <p className="label mb-1">Failing tests</p>
          <ul className="grid gap-1 font-mono text-[0.72rem] leading-snug">
            {ids.map((id) => (
              <li key={id}>
                <Breakable text={id} />
              </li>
            ))}
          </ul>
        </div>
      )}
      {cell.gates.length > 0 && (
        <div>
          <p className="label mb-1">Gates</p>
          <ul className="grid gap-2">
            {cell.gates.map((g) => (
              <li key={g.id} className="grid grid-cols-[2.6rem_1fr] gap-x-2 text-[0.9rem] leading-snug">
                <span className="font-mono text-[0.75rem]">
                  <span aria-hidden>{g.ok ? '✓' : '·'}</span> {g.id.replace('C4ab', 'C4')}
                  <span className="sr-only">{g.ok ? ' holds' : ' does not hold'}</span>
                </span>
                <span>
                  {GATES[g.id] ?? g.id}
                  {(g.detail || g.reason) && (
                    <span className="block font-mono text-[0.7rem] text-muted [overflow-wrap:anywhere]">
                      {[g.reason, g.detail].filter(Boolean).join(' · ')}
                    </span>
                  )}
                </span>
              </li>
            ))}
          </ul>
        </div>
      )}
      {cell.probe && (
        <p className="text-[0.9rem]">
          <span className="label mr-2">Probe</span>
          {cell.probe.origin === 'porter' ? 'written by the independent porter' : 'hand-written and calibrated like any other'}
          <span className="ml-2 font-mono text-[0.7rem] text-muted">sha {cell.probe.sha.slice(0, 12)}</span>
        </p>
      )}
    </div>
  );
}

function Triangle({ um, up, lt, line, chip }: { um: string; up: string; lt: string; line: string; chip: Row['cells'][number]['chip'] }) {
  return (
    <div className="relative grid grid-cols-2 gap-x-6 gap-y-8 text-center">
      <svg aria-hidden className="pointer-events-none absolute inset-0 h-full w-full" preserveAspectRatio="none" viewBox="0 0 100 100">
        <path d="M25 22 L75 22 L50 80 Z" fill="none" stroke="rgb(var(--rule))" strokeWidth="0.8" vectorEffect="non-scaling-stroke" />
      </svg>
      <Node k="U⁻" sub="upstream before fix" v={um} />
      <Node k="U⁺" sub="upstream after fix" v={up} />
      <div className="col-span-2 mx-auto">
        <Node k={line} sub="this line" v={lt}>
          <Chip chip={chip} className="mt-1" />
        </Node>
      </div>
      <span className="sr-only">{`${CHIP_META[chip].word}.`}</span>
    </div>
  );
}

function Node({ k, sub, v, children }: { k: string; sub: string; v: string; children?: React.ReactNode }) {
  return (
    <div className="relative mx-auto min-w-[9rem] rounded-chip border border-rule bg-surface px-3 py-2">
      <p className="font-mono text-sm">{k}</p>
      <p className="text-[0.75rem] text-muted">{sub}</p>
      <p className="mt-1 font-mono text-[0.8rem] font-medium">{v}</p>
      {children}
    </div>
  );
}

function Treatment({ row }: { row: Row }) {
  const c = row.campaign;
  if (c.treatment === 'pr') {
    return (
      <div className="grid gap-2 text-[0.95rem]">
        <p className="flex flex-wrap items-center gap-x-4 gap-y-1">
          <TreatmentLink href={c.link} icon="pr">
            Open the candidate backport, PR {prNum(c.link)}
          </TreatmentLink>
          {c.fail_to_pass && (
            <span className="font-mono text-[0.8rem]">
              probe {c.fail_to_pass.before[0]}×{c.fail_to_pass.before.length} → {c.fail_to_pass.after[0]}×{c.fail_to_pass.after.length}
            </span>
          )}
        </p>
        {c.reason === 'ALREADY_PUBLISHED' && <p className="text-muted">Published earlier by the first end-to-end run; the campaign did not open a second PR.</p>}
        {c.precedent && (
          <p className="text-muted">
            Applies precedent {c.precedent} (adopt upstream&rsquo;s test changes), stored from the answer to{' '}
            <a className="link" href={site.query.issue}>
              question {prNum(site.query.issue)}
            </a>
            {c.asked ? ', which this CVE asked.' : c.waited_on ? '; this CVE waited for it instead of asking again.' : '.'}
          </p>
        )}
        {c.stacked_on && (
          <p className="text-muted">
            Stacked on Heirloom&rsquo;s own backport{' '}
            <a className="link" href={c.stacked_on}>
              {prNum(c.stacked_on)}
            </a>
            {c.depends_on?.length ? ` (${c.depends_on.join(', ')})` : ''}: the upstream fix rewrites lines that fix introduced.
          </p>
        )}
      </div>
    );
  }
  return (
    <div className="grid gap-2 text-[0.95rem]">
      <p className="flex flex-wrap items-center gap-x-4 gap-y-1">
        <TreatmentLink href={c.link} icon="issue">
          Open the evidence, issue {prNum(c.link)}
        </TreatmentLink>
        <span className="font-mono text-[0.75rem] text-muted">{c.verdict.replaceAll('_', ' ')}{c.reason ? ` · ${c.reason}` : ''}</span>
      </p>
      <p className="text-muted">
        {c.verdict === 'NOT_AFFECTED_PROVEN'
          ? 'No code: the probe proved 4.2 is not affected, so the evidence is published instead of a patch.'
          : `No code: ${c.reason && REASONS[c.reason] ? REASONS[c.reason] : 'it could not prove either way'}, so it published the evidence instead of a guess.`}
      </p>
    </div>
  );
}

function TreatmentLink({ href, icon, children }: { href: string; icon: 'pr' | 'issue'; children: React.ReactNode }) {
  const Icon = icon === 'pr' ? GitPullRequest : FileText;
  return (
    <a
      href={href}
